const WORD_PATTERN_OLD = /[\p{L}\p{N}]+(?:[''-][\p{L}\p{N}]+)*/gu;  // Missing U+2019
const WORD_PATTERN_NEW = /[\p{L}\p{N}]+(?:[''-][\p{L}\p{N}]+)*/gu;  // Has U+2019

function tokenize(text, pattern) {
  return text.match(pattern) ?? [];
}

function wordCount(text, pattern) {
  return tokenize(text, pattern).length;
}

// Test with actual U+2019 character
const testString = "don’t";  // don + U+2019 + t
console.log(`Test string: "don’t" (contains U+2019)`);
console.log(`With OLD pattern (no U+2019): wordCount = ${wordCount(testString, WORD_PATTERN_OLD)}`);
console.log(`With NEW pattern (has U+2019): wordCount = ${wordCount(testString, WORD_PATTERN_NEW)}`);
console.log(`Expected: 1 in both cases`);
